INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明廷豁免江西灾区税粮", "description": "景泰八年正月戊辰，朝廷免除江西受灾地区应缴纳的税粮。", "start_year": 1457, "end_year": 1457, "time_original": "景泰八年正月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "adfa6ff8-8887-5893-b4e4-ccf805a8f469"}, {"title": "景帝带病到南郊斋宫留宿", "description": "景泰八年正月丁丑，病中的明景帝朱祁钰乘舆前往南郊斋宫，并在此留宿。", "start_year": 1457, "end_year": 1457, "time_original": "景泰八年正月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "622a7801-194d-5523-89bd-0598b7b8c09e"}, {"title": "景帝未同意群臣册立太子的请求", "description": "景泰八年正月己卯，群臣请求册立皇太子，明景帝朱祁钰没有同意。", "start_year": 1457, "end_year": 1457, "time_original": "景泰八年正月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b4c059b8-f350-598c-88e7-303279709a01"}, {"title": "朱祁镇恢复皇帝位，并改元天顺", "description": "景泰8年（1457年）正月壬午，朱祁镇恢复皇帝位，并改元天顺。", "start_year": 1457, "end_year": 1457, "time_original": "景泰8年（1457年）正月壬午", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "febef8c3-857e-5bbf-9e2b-b2e32686d1ad"}, {"title": "明英宗废朱祁钰为郕王并迁往西内", "description": "景泰八年二月乙未，复位的明英宗朱祁镇废朱祁钰为郕王，将他迁往西内，原为皇太后的吴氏等恢复旧封号。", "start_year": 1457, "end_year": 1457, "time_original": "景泰八年二月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "05b22b67-1c38-51eb-a3cc-7f724ef1e85f"}, {"title": "朱祁钰在西宫去世", "description": "景泰八年二月癸丑，被废为郕王的朱祁钰在西宫去世。《明史》本纪记其年三十。", "start_year": 1457, "end_year": 1457, "time_original": "景泰八年二月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1663eb32-d37a-57cf-a0c8-034e98047ac7"}, {"title": "明廷谥朱祁钰为戾，以亲王礼葬于西山", "description": "景泰八年二月条记，朝廷为朱祁钰上谥号戾，拆毁先前营建的寿陵，以亲王礼把他安葬在西山，拨武成中卫军二百户守护。", "start_year": 1457, "end_year": 1457, "time_original": "景泰八年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "236ed6af-a2d8-5aff-8024-16ec5eadff8e"}, {"title": "明宪宗下诏恢复朱祁钰帝号", "description": "成化十一年十二月戊子，明宪宗朱见深下诏恢复叔父朱祁钰的皇帝称号，命大臣议定谥号。", "start_year": 1476, "end_year": 1476, "time_original": "成化十一年十二月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6d188136-7a51-50a5-b06e-47f89a4da015"}, {"title": "明廷为朱祁钰上尊谥，命修陵并依诸帝陵祭祀", "description": "《明史》在成化十一年十二月条记载，恢复朱祁钰帝号后，朝廷上尊谥，下诏整修陵寝，祭祀依照其他皇帝陵寝的礼制。", "start_year": 1476, "end_year": 1476, "time_original": "成化十一年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "78b57fa0-b83b-5eaf-8ef7-c52234ede023"}, {"title": "王复、赵荣出使也先军营，在土城拜见太上皇", "description": "正统十四年十月己未，右通政王复与太常少卿赵荣出使瓦剌太师也先的军营，在土城拜见太上皇朱祁镇。", "start_year": 1449, "end_year": 1449, "time_original": "正统十四年十月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e388db22-76d9-56ef-9c8a-dcb31bd519d6"}, {"title": "江渊回乡奔丧", "description": "景泰3年（1452年）九月，江渊回乡奔丧。", "start_year": 1452, "end_year": 1452, "time_original": "景泰3年（1452年）九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "9c0541ed-95c1-5669-8189-8d5c81b940eb"}, {"title": "江渊返回原任", "description": "景泰4年（1453年）四月，江渊返回原任。", "start_year": 1453, "end_year": 1453, "time_original": "景泰4年（1453年）四月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "b795f7ef-c88c-5f9f-a8c5-a292edef2a23"}, {"title": "王文离职守丧", "description": "景泰4年（1453年）五月，王文离职守丧。", "start_year": 1453, "end_year": 1453, "time_original": "景泰4年（1453年）五月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "86a196bc-8a7b-58b4-b1f2-f2d8e003b385"}, {"title": "王文恢复任职", "description": "景泰4年（1453年）九月，王文恢复任职。", "start_year": 1453, "end_year": 1453, "time_original": "景泰4年（1453年）九月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "d07995e7-af04-5f65-8f47-2e7481a07f51"}, {"title": "徐有贞受命治理沙湾河患", "description": "景泰四年十月甲午，朝廷任命谕德徐有贞为左佥都御史，派他治理沙湾黄河决口。《英宗实录》作右佥都御史，卷末校记保留两种写法。", "start_year": 1453, "end_year": 1453, "time_original": "景泰四年十月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "05cfb0e1-cd17-5cfc-ab23-f31fd4191813"}]'::jsonb)
